CREATE TABLE cinemas (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, city VARCHAR(255) NOT NULL, address VARCHAR(255), phone VARCHAR(255), description VARCHAR(6000), active BOOLEAN NOT NULL);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, phone VARCHAR(255), avatar VARCHAR(255), role VARCHAR(255) NOT NULL, cinema_id BIGINT, enabled BOOLEAN NOT NULL, auth_version INT NOT NULL, FOREIGN KEY(cinema_id) REFERENCES cinemas(id), CHECK(role IN ('CUSTOMER','ADMIN','STAFF')));
CREATE TABLE reset_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, token_hash VARCHAR(255) NOT NULL UNIQUE, expires_at DATETIME(6) NOT NULL, used BOOLEAN NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE genres (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, active BOOLEAN NOT NULL);
CREATE TABLE people (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, biography VARCHAR(255), active BOOLEAN NOT NULL);
CREATE TABLE movies (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, description VARCHAR(6000), poster VARCHAR(255), banner VARCHAR(255), trailer VARCHAR(255), age_rating VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, duration INT NOT NULL, release_date DATE, featured BOOLEAN NOT NULL, active BOOLEAN NOT NULL, CHECK(duration>0));
CREATE TABLE movie_genres (id BIGINT AUTO_INCREMENT PRIMARY KEY, movie_id BIGINT NOT NULL, genre_id BIGINT NOT NULL, UNIQUE(movie_id,genre_id), FOREIGN KEY(movie_id) REFERENCES movies(id), FOREIGN KEY(genre_id) REFERENCES genres(id));
CREATE TABLE credits (id BIGINT AUTO_INCREMENT PRIMARY KEY, movie_id BIGINT NOT NULL, person_id BIGINT NOT NULL, kind VARCHAR(255) NOT NULL, UNIQUE(movie_id,person_id,kind), FOREIGN KEY(movie_id) REFERENCES movies(id), FOREIGN KEY(person_id) REFERENCES people(id));
CREATE TABLE rooms (id BIGINT AUTO_INCREMENT PRIMARY KEY, cinema_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, format VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL, UNIQUE(cinema_id,name), FOREIGN KEY(cinema_id) REFERENCES cinemas(id));
CREATE TABLE seats (id BIGINT AUTO_INCREMENT PRIMARY KEY, room_id BIGINT NOT NULL, label VARCHAR(255) NOT NULL, row_label VARCHAR(255) NOT NULL, position INT NOT NULL, type VARCHAR(255) NOT NULL, couple_group VARCHAR(255), active BOOLEAN NOT NULL, UNIQUE(room_id,label), UNIQUE(room_id,row_label,position), FOREIGN KEY(room_id) REFERENCES rooms(id));
CREATE TABLE showtimes (id BIGINT AUTO_INCREMENT PRIMARY KEY, movie_id BIGINT NOT NULL, room_id BIGINT NOT NULL, starts_at DATETIME(6) NOT NULL, ends_at DATETIME(6) NOT NULL, language VARCHAR(255), format VARCHAR(255), status VARCHAR(255) NOT NULL, surcharge BIGINT NOT NULL, FOREIGN KEY(movie_id) REFERENCES movies(id), FOREIGN KEY(room_id) REFERENCES rooms(id), INDEX(room_id,starts_at), CHECK(ends_at>starts_at), CHECK(surcharge>=0));
CREATE TABLE prices (id BIGINT AUTO_INCREMENT PRIMARY KEY, cinema_id BIGINT NOT NULL, seat_type VARCHAR(255) NOT NULL, day_type VARCHAR(255) NOT NULL, from_minute INT NOT NULL, to_minute INT NOT NULL, amount BIGINT NOT NULL, FOREIGN KEY(cinema_id) REFERENCES cinemas(id), CHECK(amount>0), CHECK(from_minute>=0 AND from_minute<to_minute AND to_minute<=1440));
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, kind VARCHAR(255) NOT NULL, image VARCHAR(255), description VARCHAR(255), price BIGINT NOT NULL, active BOOLEAN NOT NULL, CHECK(price>=0));
CREATE TABLE vouchers (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE, description VARCHAR(255), kind VARCHAR(255) NOT NULL, value BIGINT NOT NULL, minimum BIGINT NOT NULL, maximum BIGINT NOT NULL, quota INT NOT NULL, per_user INT NOT NULL, starts_at DATETIME(6) NOT NULL, ends_at DATETIME(6) NOT NULL, active BOOLEAN NOT NULL, CHECK(value>0 AND minimum>=0 AND maximum>=0 AND quota>0 AND per_user>0), CHECK(ends_at>starts_at));
CREATE TABLE orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE, user_id BIGINT NOT NULL, showtime_id BIGINT NOT NULL, voucher_id BIGINT, status VARCHAR(255) NOT NULL, created_at DATETIME(6) NOT NULL, expires_at DATETIME(6) NOT NULL, paid_at DATETIME(6), subtotal BIGINT NOT NULL, discount BIGINT NOT NULL, total BIGINT NOT NULL, frozen BOOLEAN NOT NULL, movie_title VARCHAR(255), cinema_name VARCHAR(255), room_name VARCHAR(255), show_starts_at DATETIME(6), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(showtime_id) REFERENCES showtimes(id), FOREIGN KEY(voucher_id) REFERENCES vouchers(id), INDEX(status,expires_at), INDEX(user_id,created_at), CHECK(total>=0 AND discount>=0));
CREATE TABLE inventory (id BIGINT AUTO_INCREMENT PRIMARY KEY, showtime_id BIGINT NOT NULL, seat_id BIGINT NOT NULL, order_id BIGINT, status VARCHAR(255) NOT NULL, expires_at DATETIME(6), UNIQUE(showtime_id,seat_id), FOREIGN KEY(showtime_id) REFERENCES showtimes(id), FOREIGN KEY(seat_id) REFERENCES seats(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE order_seats (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, seat_id BIGINT NOT NULL, label VARCHAR(255), seat_type VARCHAR(255), price BIGINT NOT NULL, UNIQUE(order_id,seat_id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(seat_id) REFERENCES seats(id));
CREATE TABLE order_products (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, name VARCHAR(255), quantity INT NOT NULL, price BIGINT NOT NULL, UNIQUE(order_id,product_id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id), CHECK(quantity>0 AND quantity<=20));
CREATE TABLE voucher_uses (id BIGINT AUTO_INCREMENT PRIMARY KEY, voucher_id BIGINT NOT NULL, order_id BIGINT NOT NULL UNIQUE, user_id BIGINT NOT NULL, status VARCHAR(255) NOT NULL, expires_at DATETIME(6) NOT NULL, FOREIGN KEY(voucher_id) REFERENCES vouchers(id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(voucher_id,status,expires_at));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, provider VARCHAR(255) NOT NULL, request_id VARCHAR(255) NOT NULL UNIQUE, external_order_id VARCHAR(255) NOT NULL UNIQUE, transaction_id VARCHAR(255) UNIQUE, status VARCHAR(255) NOT NULL, pay_url VARCHAR(255), amount BIGINT NOT NULL, result_code INT, reconciliation BOOLEAN NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE tickets (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, seat_id BIGINT NOT NULL, showtime_id BIGINT NOT NULL, code VARCHAR(255) NOT NULL UNIQUE, token VARCHAR(255) NOT NULL UNIQUE, status VARCHAR(255) NOT NULL, checked_in_at DATETIME(6), checked_in_by BIGINT, UNIQUE(showtime_id,seat_id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(seat_id) REFERENCES seats(id), FOREIGN KEY(showtime_id) REFERENCES showtimes(id), FOREIGN KEY(checked_in_by) REFERENCES users(id));
CREATE TABLE point_ledger (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, order_id BIGINT NOT NULL UNIQUE, points BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE favorites (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, movie_id BIGINT NOT NULL, UNIQUE(user_id,movie_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(movie_id) REFERENCES movies(id));
CREATE TABLE reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, movie_id BIGINT NOT NULL, stars INT NOT NULL, comment VARCHAR(2000), visible BOOLEAN NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE(user_id,movie_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(movie_id) REFERENCES movies(id), CHECK(stars BETWEEN 1 AND 5));
CREATE TABLE subscriptions (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, movie_id BIGINT NOT NULL, email BOOLEAN NOT NULL, sent BOOLEAN NOT NULL, UNIQUE(user_id,movie_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(movie_id) REFERENCES movies(id));
CREATE TABLE notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, subject VARCHAR(255), body VARCHAR(6000), seen BOOLEAN NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE contents (id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(255) NOT NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, image VARCHAR(255), link VARCHAR(255), body TEXT, active BOOLEAN NOT NULL, published_at DATETIME(6));
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT, action VARCHAR(255) NOT NULL, target VARCHAR(255), created_at DATETIME(6) NOT NULL, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE mail_jobs (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, dedup_key VARCHAR(255) NOT NULL UNIQUE, destination VARCHAR(255), subject VARCHAR(255), body VARCHAR(12000), attempts INT NOT NULL, next_attempt_at DATETIME(6) NOT NULL, sent_at DATETIME(6), FOREIGN KEY(user_id) REFERENCES users(id));
